@file:JvmName("Extensions")

package org.genhttp.modules.clientcaching

import org.genhttp.api.infrastructure.ServerHost

/**
 * Adds a concern to the host that tags the content generated by the server with ETags, so clients can
 * validate their cached responses.
 *
 * @return The host the concern has been added to
 */
public fun ServerHost.clientCaching(): ServerHost {
    add(ClientCache.validation())
    return this
}
